        r,c=stack.pop()
        if (r,c) in seen or not (0<=r<h and 0<=c<w) or grid[r][c]!=bg: continue
        seen.add((r,c))
        stack += [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2 and any((r, q) in seen for q in range(max(0,c-2),min(w,c+3))):
                for k,v in enumerate((1,5,5,5,5)):
                    q=c-2+k
                    if 0<=q<w and grid[r][q]==bg: out[r][q]=v
    return out

